(function(root){'use strict';const N=root.NeonCombat,S=N.Stats266;let box,g,at=0;const fmt=v=>typeof v==='number'?String(Math.round(v*1000)/1000):String(v);function table(parent,rows,headers){const t=document.createElement('table'),head=document.createElement('tr');for(const h of headers){const c=document.createElement('th');c.textContent=h;head.append(c);}t.append(head);for(const row of rows){const tr=document.createElement('tr');for(const v of row){const c=document.createElement('td');c.textContent=fmt(v);tr.append(c);}t.append(tr);}parent.replaceChildren(t);}
function render(force=false){if(!box||!g)return;S.enable(g,box.open&&!box.parentNode?.hidden);const now=performance.now();if(!force&&now-at<500)return;at=now;const pick=box.querySelector('[data-character]'),old=pick.value,defs=S.registry(g),live=S.entities(g),signature=defs.map(x=>x.id).join('|')+';'+live.map(e=>e.id).join('|');if(signature!==pick.dataset.ids){pick.replaceChildren();for(const r of defs){const o=document.createElement('option');o.value=r.id;o.textContent=r.kind+' · '+r.name;pick.append(o);}for(const e of live){const o=document.createElement('option');o.value='live:'+e.id;o.textContent='LIVE #'+e.id+' · '+(e.name||e.type);pick.append(o);}pick.dataset.ids=signature;if([...pick.options].some(o=>o.value===old))pick.value=old;else pick.value='live:'+g.player.id;}
 const r=S.inspect(g,pick.value);box.querySelector('[data-status]').textContent=r.name+' · '+r.classification+' · '+(r.instance==null?'registry only':'live #'+r.instance)+' · modifiers: '+(r.modifiers.join(', ')||'none observed');table(box.querySelector('[data-stats]'),r.rows.map(x=>[x.label,x.configured,x.current,x.measured,x.difference,x.unit,x.source+([x.configured,x.current,x.measured].every(v=>v==='N/A')?' · '+x.reason:'')]),['Statistic','Configured','Live','Measured','Difference','Units','Source / limitation']);box.querySelector('[data-samples]').textContent=JSON.stringify(r.samples,null,2);
 const selected=[...box.querySelectorAll('[data-hero]:checked')].map(x=>x.value),metrics=['Forward walk','Running','Run acceleration','Jump height','Forward jump distance','Dodge distance','Dodge total observed duration','Attack movement displacement','Recovery phase duration','Defense maximum','Defense regeneration'];table(box.querySelector('[data-comparison]'),metrics.map(label=>[label,...selected.map(id=>{const row=S.inspect(g,id,true).rows.find(x=>x.label===label);return row?`config ${fmt(row.configured)} / live ${fmt(row.current)} / measured ${fmt(row.measured)}`:'N/A';})]),['Metric',...selected.map(id=>N.HEROES[id].name)]);}
function mount(parent,game){g=game;if(!box){box=document.createElement('details');box.id='stats266';box.innerHTML='<summary>CHARACTER STATS & HERO COMPARISON · GATE B</summary><p>Read-only. Open this tab to measure actual movement. Walk/run for 60 consecutive simulation frames in one direction on a clear floor. Enemy samples follow their actual AI. Run/jump/dodge samples do not alter balance. Catalog-only values remain N/A until observed.</p><label>Character <select data-character aria-label="Character statistics"></select></label><p data-status></p><div class="stats-scroll266" data-stats></div><details><summary>Measurement timestamps and context</summary><pre data-samples></pre></details><h4>Hero comparison</h4><div data-heroes></div><div class="stats-scroll266" data-comparison></div><p>N/A means undefined or not measured. See Combat Laboratory for registered move timing and temporary damage/recovery tests. Unadapted values stay N/A.</p>';const list=box.querySelector('[data-heroes]');for(const[id,d]of Object.entries(N.HEROES)){const label=document.createElement('label'),c=document.createElement('input');c.type='checkbox';c.value=id;c.dataset.hero='';c.checked=true;c.onchange=()=>render(true);label.append(c,document.createTextNode(d.name+' '));list.append(label);}box.querySelector('[data-character]').onchange=()=>render(true);box.ontoggle=()=>{render(true);};}if(box.parentNode!==parent)parent.prepend(box);render();}
root.StatsUI266={mount,render};
})(globalThis);
